import { useState, useEffect } from 'react';
import { useHistory } from 'react-router-dom';

function LoginDetails() {
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [isSignup, setIsSignup] = useState(false);
    const [errorMessage, setErrorMessage] = useState('');
    const navigate = useNavigate();

    useEffect(() => {
        const token = localStorage.getItem('token');
        if (token) {
            navigate('/profile');
        }
    }, [navigate]);


    const handleSubmit = (e) => {
        e.preventDefault();
        const endpoint = isSignup ? 'http://localhost:3001/signup' : 'http://localhost:3001/login';
        fetch(endpoint, {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({email, password})
        })
        .then(response => {
            if (!response.ok) {
                return response.text().then(text => { throw new Error(text) });
            }
            return response.json();
        })
        .then(data => {
            const userId = data.userId;
            const token = data.token;
            localStorage.setItem('userId', userId);
            localStorage.setItem('token', token);
            navigate('/profile');
        })
        .catch(error => {
            console.error('Erreur lors de la connexion', error);
            setErrorMessage(error.message);
        });
    }

    return (
        <div>
            <h2>{isSignup ? 'Inscription' : 'Connexion'}</h2>
            {errorMessage && <p style={{color: 'red'}}>{errorMessage}</p>}
            <form onSubmit={handleSubmit}>
                <input type="email" placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} required />
                <input type="password" placeholder="Mot de passe" value={password} onChange={(e) => setPassword(e.target.value)} required />
                <button type="submit">{isSignup ? 'S\'inscrire' : 'Se connecter'}</button>
            </form>
            <p>{isSignup ? 'Vous avez déjà un compte ?' : 'Vous n\'avez pas de compte ?'}</p>
            <button onClick={() => setIsSignup(!isSignup)}>{isSignup ? 'Se connecter' : 'S\'inscrire'}</button>
        </div>
    );

}
export default LoginDetails;
